import { useState } from 'react';
import '../styles/stepper.css';

export default function Stepper({ Value: initialValue = '1' }) {
  const [value, setValue] = useState(parseInt(initialValue, 10));
  const min = 0;
  const max = 10;

  const handleDecrement = () => {
    setValue(prev => Math.max(prev - 1, min));
  };

  const handleIncrement = () => {
    setValue(prev => Math.min(prev + 1, max));
  };

  const handleKeyDown = (e) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      handleDecrement();
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      handleIncrement();
    }
  };

  return (
    <div
      className="stepper"
      role="spinbutton"
      aria-valuenow={value}
      aria-valuemin={min}
      aria-valuemax={max}
      aria-label="Numeric stepper"
      onKeyDown={handleKeyDown}
      tabIndex={0}
    >
      <button
        className="stepper-button"
        onClick={handleDecrement}
        aria-label="Decrease"
        disabled={value === min}
      >
        <svg
          className="stepper-icon"
          viewBox="0 0 12 12"
          width="12"
          height="12"
        >
          <line x1="1" y1="6" x2="11" y2="6" stroke="currentColor" strokeWidth="2" />
        </svg>
      </button>
      <span className="stepper-value">{value}</span>
      <button
        className="stepper-button"
        onClick={handleIncrement}
        aria-label="Increase"
        disabled={value === max}
      >
        <svg
          className="stepper-icon"
          viewBox="0 0 12 12"
          width="12"
          height="12"
        >
          <line x1="1" y1="6" x2="11" y2="6" stroke="currentColor" strokeWidth="2" />
          <line x1="6" y1="1" x2="6" y2="11" stroke="currentColor" strokeWidth="2" />
        </svg>
      </button>
    </div>
  );
}

