import React, { useState, useRef } from 'react';
import '../styles/stepper.css';

export default function Stepper({ Value: initialValue = '1' }) {
  const [value, setValue] = useState(parseInt(initialValue, 10));
  const rootRef = useRef(null);

  const handleDecrement = () => {
    setValue(prev => Math.max(prev - 1, 0));
  };

  const handleIncrement = () => {
    setValue(prev => Math.min(prev + 1, 10));
  };

  const handleKeyDown = (e) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      handleDecrement();
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      handleIncrement();
    }
  };

  return (
    <div
      ref={rootRef}
      className="stepper"
      role="spinbutton"
      aria-valuenow={value}
      aria-valuemin="0"
      aria-valuemax="10"
      aria-label="Stepper: adjust value"
      onKeyDown={handleKeyDown}
      tabIndex="0"
    >
      <button
        className="stepper__decrement"
        onClick={handleDecrement}
        aria-label="Decrease"
        type="button"
      >
        <div className="stepper__icon stepper__icon--minus">
          <div className="stepper__icon-bar stepper__icon-bar--horizontal" />
        </div>
      </button>
      <p className="stepper__value">{value}</p>
      <button
        className="stepper__increment"
        onClick={handleIncrement}
        aria-label="Increase"
        type="button"
      >
        <div className="stepper__icon stepper__icon--plus">
          <div className="stepper__icon-bar stepper__icon-bar--horizontal" />
          <div className="stepper__icon-bar stepper__icon-bar--vertical" />
        </div>
      </button>
    </div>
  );
}

