import { useState, useRef } from 'react';
import '../styles/stepper.css';

export default function Stepper({ Value = '1', ariaLabel = 'Step counter' }) {
  const [value, setValue] = useState(parseInt(Value, 10));
  const ref = useRef(null);

  const handleDecrement = () => {
    setValue((prev) => Math.max(0, prev - 1));
  };

  const handleIncrement = () => {
    setValue((prev) => Math.min(10, prev + 1));
  };

  const handleKeyDown = (e) => {
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      handleDecrement();
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      handleIncrement();
    }
  };

  return (
    <div
      ref={ref}
      className="stepper"
      role="spinbutton"
      aria-valuenow={value}
      aria-valuemin="0"
      aria-valuemax="10"
      aria-label={ariaLabel}
      tabIndex="0"
      onKeyDown={handleKeyDown}
    >
      <button
        className="stepper-button"
        onClick={handleDecrement}
        aria-label="Decrease"
      >
        <div className="stepper-icon">
          <div className="stepper-icon-bar" />
        </div>
      </button>
      <div className="stepper-value">{value}</div>
      <button
        className="stepper-button"
        onClick={handleIncrement}
        aria-label="Increase"
      >
        <div className="stepper-icon">
          <div className="stepper-icon-bar stepper-icon-bar--horizontal" />
          <div className="stepper-icon-bar stepper-icon-bar--vertical" />
        </div>
      </button>
    </div>
  );
}

