import React, { useState } from 'react';

export default function Field({
  className,
  state = 'Default',
  label,
  value = '',
  onChange,
  errorMessage,
  ...props
}) {
  const isError = state === 'Error';
  const errorId = isError && errorMessage ? 'field-error-message' : undefined;

  return (
    <div>
      {label && (
        <label htmlFor="field-input" className="field-label">
          {label}
        </label>
      )}
      <input
        id="field-input"
        type="text"
        className={className || `field ${isError ? 'field--error' : ''}`}
        value={value}
        onChange={onChange}
        aria-invalid={isError}
        aria-describedby={errorId}
        {...props}
      />
      {isError && errorMessage && (
        <div id={errorId} className="field-error-message">
          {errorMessage}
        </div>
      )}
    </div>
  );
}

