import { useState } from 'react';
import '../styles/field.css';

export default function Field({ className, state = 'Default', label = 'Input', errorMessage = '' }) {
  const [value, setValue] = useState('');
  const isError = state === 'Error';
  const errorId = 'field-error';

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--gap-s)' }}>
      <label id="field-label" htmlFor="field-input">{label}</label>
      <input
        id="field-input"
        type="text"
        className={`field ${isError ? 'field--error' : ''} ${className || ''}`}
        value={value}
        onChange={(e) => setValue(e.target.value)}
        aria-invalid={isError}
        aria-describedby={errorId}
        aria-labelledby="field-label"
      />
      <div
        id={errorId}
        style={{
          color: 'var(--field-border-error)',
          fontSize: '12px',
          minHeight: '0',
          visibility: isError && errorMessage ? 'visible' : 'hidden',
        }}
      >
        {errorMessage}
      </div>
    </div>
  );
}

